import { TypedEventTarget } from "../../Util/TypedEventTarget";
import { PaintVoxelData } from "../../Voxels/Types/PaintVoxelData";
export class VoxelPathSegment extends TypedEventTarget {
    path;
    index;
    static CreateNew(data) {
        return {
            start: data.start ? data.start : [0, 0, 0],
            end: data.end ? data.end : [0, 0, 0],
            voxel: data.voxel ? data.voxel : PaintVoxelData.Create(),
            transient: data.transient ? data.transient : undefined,
        };
    }
    start;
    end;
    voxel;
    transient = false;
    constructor(path, index, data) {
        super();
        this.path = path;
        this.index = index;
        this.start = data.start;
        this.end = data.end;
        this.voxel = data.voxel;
        this.transient = data.transient || false;
    }
    setPoints([sx, sy, sz], [ex, ey, ez]) {
        let updated = false;
        if (this.start[0] != sx || this.start[1] != sy || this.start[2] != sz) {
            updated = true;
        }
        this.start[0] = sx;
        this.start[1] = sy;
        this.start[2] = sz;
        if (this.end[0] != ex || this.end[1] != ey || this.end[2] != ez) {
            updated = true;
        }
        this.end[0] = ex;
        this.end[1] = ey;
        this.end[2] = ez;
        if (updated) {
            this.dispatch("updated", {});
        }
    }
    getPoint(point) {
        if (point == 0)
            return this.start;
        if (point == 1)
            return this.end;
        throw new Error(`Point must be 0 or 1 get ${point}`);
    }
    setPoint(point, vec) {
        if (point == 0) {
            return this.setPoints(vec, this.end);
        }
        if (point == 1) {
            return this.setPoints(this.start, vec);
        }
        throw new Error(`Point must be 0 or 1 get ${point}`);
    }
    toJSON() {
        return {
            start: [...this.start],
            end: [...this.end],
            voxel: { ...this.voxel },
            ...(this.transient ? { transient: true } : {}),
        };
    }
}
export class VoxelPath extends TypedEventTarget {
    data;
    static CreateNew(data) {
        return {
            segments: data.segments ? data.segments : [],
        };
    }
    segments = [];
    constructor(data) {
        super();
        this.data = data;
        for (let i = 0; i < data.segments.length; i++) {
            this.segments.push(new VoxelPathSegment(this, i, data.segments[i]));
        }
    }
    get totalSegments() {
        return this.segments.length;
    }
    lastSegment() {
        if (!this.segments.length)
            return null;
        return this.segments[(this.totalSegments - 1) % this.totalSegments];
    }
    firstSegment() {
        if (!this.segments.length)
            return null;
        return this.segments[0];
    }
    addSegment(data) {
        const segment = new VoxelPathSegment(this, this.segments.length, data);
        this.segments.push(segment);
        this.dispatch("segmentAdded", segment);
        return true;
    }
    removeSegment(segment) {
        for (let i = this.segments.length - 1; i > -1; i--) {
            this.segments[i].index--;
            if (this.segments[i] == segment) {
                console.log("found segment to remove", i);
                this.segments.splice(i, 1);
                break;
            }
        }
        this.dispatch("segmentRemoved", segment);
        return false;
    }
    removePoint(segmentIndex, pointIndex) {
        if (!this.segments.length)
            return false;
        if (!this.segments[segmentIndex])
            return false;
        if (segmentIndex > 0) {
            const segment = this.segments[segmentIndex];
            const previousSegment = this.segments.at(segmentIndex - 1);
            if (pointIndex == 0) {
                previousSegment.setPoints(previousSegment.start, segment.end);
            }
            if (pointIndex == 1) {
                previousSegment.setPoints(previousSegment.start, segment.start);
            }
            this.removeSegment(segment);
        }
        else {
            this.removeSegment(this.segments[0]);
        }
    }
    toJSON() {
        const segments = [];
        for (let i = 0; i < this.segments.length; i++) {
            segments.push(this.segments[i].toJSON());
        }
        return {
            segments,
        };
    }
}
